"""Apply the edition and activation UI to the existing polished public site."""
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
site=ROOT/'saas_site/dist'
account=site/'account.html'
html=account.read_text(encoding='utf-8')
if 'id="edition"' not in html:
    html=html.replace('<div class="billing-options">','<label for="edition">Choose your edition</label><select id="edition"><option value="desktop">Desktop — standalone local editor</option><option value="plugins">Editor Plugins — After Effects, Premiere Pro & Resolve Studio</option></select><p class="field-note">Each edition is purchased separately. Both use your computer for editing. The Plugin edition includes all three editor integrations.</p><div class="billing-options">')
    html=html.replace('<button class="text-button" id="logout">','<section class="activation-section"><h3>Activate your computer</h3><p>Open Hinglish Editor or its plugin, choose Activate, then enter the code shown there.</p><form id="device-form"><label for="device-code">Activation code</label><input id="device-code" maxlength="9" pattern="[A-Za-z0-9]{4}-[A-Za-z0-9]{4}" placeholder="ABCD-EFGH" required><button class="button" type="submit">Check this device</button></form><p id="device-summary" role="status"></p><button id="approve-device" class="button primary" hidden>Approve this computer</button><h3>Your computers</h3><div id="devices"></div><h3>Your downloads</h3><div id="downloads"></div></section><button class="text-button" id="logout">')
html=html.replace('Payment, email and rendering setup','Payment, email and activation setup').replace('?v=20261014c','?v=20261015a')
account.write_text(html,encoding='utf-8')
jsfile=site/'assets/account.js';js=jsfile.read_text(encoding='utf-8')
js=js.replace('async function api(path,data){','async function api(path,data,method){').replace("method:data===undefined?'GET':'POST'","method:method||(data===undefined?'GET':'POST')")
js=js.replace("{plan:b.dataset.plan}","{plan:b.dataset.plan,edition:$('#edition').value}")
js=js.replace("description:order.plan==='annual'?'12 months of access':'1 month of access'","description:(order.edition==='plugins'?'Editor Plugins':'Desktop')+' · '+(order.plan==='annual'?'12 months of access':'1 month of access')")
js=js.replace('Payment, email and rendering setup','Payment, email and device activation setup')
js=js.replace("$('#open-editor').hidden=!active;","$('#open-editor').hidden=!active||!config.worker_enabled;")
addon="loadDevices();loadDownloads();const subs=Object.entries(me.editions||{}).filter(([k,v])=>v.active);if(subs.length)$('#subscription-status').textContent=subs.map(([k,v])=>(k==='plugins'?'Editor Plugins':'Desktop')+' active until '+new Date(v.expires*1000).toLocaleDateString('en-IN')).join(' · ');"
js=js.replace(addon,'')
js=js.replace("$('#send-verification').disabled=!config.email_enabled;","$('#send-verification').disabled=!config.email_enabled;"+addon)
if 'async function loadDevices()' not in js:
    more='''
let verifiedCode='';
$('#edition').value=new URLSearchParams(location.search).get('edition')==='plugins'?'plugins':'desktop';
async function loadDevices(){try{const rows=await api('/api/licenses/devices');$('#devices').replaceChildren();for(const d of rows){const row=document.createElement('p'),name=document.createElement('span'),button=document.createElement('button');name.textContent=d.name+' · '+(d.edition==='plugins'?'Editor Plugins':'Desktop')+' ';button.className='text-button';button.textContent='Deactivate';button.onclick=async()=>{try{await api('/api/licenses/devices/'+d.id,undefined,'DELETE');await loadDevices();$('#device-summary').textContent='Device deactivated. This subscription remains tied to this computer. Request a replacement through Support.'}catch(e){$('#device-summary').textContent=e.message}};row.append(name,button);$('#devices').append(row)}if(!rows.length)$('#devices').textContent='No activated computers yet.'}catch(e){$('#devices').textContent=e.message}}
async function loadDownloads(){try{const v=await api('/api/downloads');$('#downloads').replaceChildren();for(const item of v.items){const a=document.createElement('a');a.href='/api/downloads/'+item.id;a.className='text-link';a.textContent=item.label+' · '+item.version;$('#downloads').append(a)}if(!v.items.length)$('#downloads').textContent=v.message}catch(e){$('#downloads').textContent=e.message}}
$('#device-form').onsubmit=async e=>{e.preventDefault();$('#approve-device').hidden=true;verifiedCode='';try{const code=$('#device-code').value.trim().toUpperCase(),d=await api('/api/licenses/pending/'+encodeURIComponent(code));verifiedCode=code;$('#device-summary').textContent='Computer: '+d.name+'. Edition: '+(d.edition==='plugins'?'Editor Plugins':'Desktop')+'. Approve only if this is your computer.';$('#approve-device').hidden=false}catch(e){$('#device-summary').textContent=e.message}};
$('#approve-device').onclick=async()=>{try{if(!verifiedCode||verifiedCode!==$('#device-code').value.trim().toUpperCase())throw Error('Check the code again before approving.');await api('/api/licenses/approve',{user_code:verifiedCode});$('#device-summary').textContent='Approved. Return to the editor; it will activate automatically.';$('#approve-device').hidden=true;verifiedCode='';setTimeout(loadDevices,6000)}catch(e){$('#device-summary').textContent=e.message}};
'''
    js=js.replace("(async()=>{displayMode",more+"\n(async()=>{displayMode")
jsfile.write_text(js,encoding='utf-8')
css=site/'assets/workspace.css'
if '.activation-section{' not in css.read_text(encoding='utf-8'):
    with css.open('a',encoding='utf-8') as handle:handle.write('\n.activation-section{margin:28px 0;border-top:1px solid #e0e5e7;padding-top:24px}.activation-section h3{font-size:18px;margin:22px 0 10px}.activation-section p,.activation-section #downloads{font-size:14px;line-height:1.7;color:#65717a}.activation-section button{margin-top:8px}#downloads a{display:block}#edition{width:100%;padding:12px;border:1px solid #d9dfe2;border-radius:5px;background:white;font:inherit;margin:10px 0}#device-code{text-transform:uppercase;letter-spacing:2px}\n')
index=site/'index.html';html=index.read_text(encoding='utf-8')
if 'id="editions"' not in html:
    html=html.replace('<section class="pricing wrap"', '<section class="workflow wrap" id="editions"><div class="section-intro"><h2>Choose where<br>you create.</h2><p>The same local editing engine. Two ways to work.</p></div><div class="price-grid"><article class="price-plan"><h3>Desktop edition</h3><p>Run Hinglish Editor as a standalone workspace on your Windows computer. Your editing runs locally, using your own CPU and GPU.</p><a class="button primary" href="/account?edition=desktop&amp;view=register">Choose Desktop</a></article><article class="price-plan"><h3>Editor Plugins edition</h3><p>Use panels and scripting integrations in After Effects, Premiere Pro and DaVinci Resolve Studio. Share one local runtime across the three editors.</p><a class="button primary" href="/account?edition=plugins&amp;view=register">Choose Editor Plugins</a><p class="field-note">Host versions and signed installer availability are checked before release.</p></article></div></section><section class="pricing wrap"')
html=html.replace('One creator account. Choose a month at a time or save with annual access.','Each edition: ₹2,000 monthly or ₹20,000 annually. Choose Desktop or Editor Plugins in your account.')
html=html.replace('Your browser is the workspace. The editing code runs on private rendering workers. Available tools and turnaround depend on connected models, GPU capacity and the processing queue.','Desktop and plugin edits run on your own Windows computer. The website manages your account, purchase and device activation. Heavy AI tools depend on your CPU, RAM, GPU and installed models. Optional cloud rendering requires a separately configured service.')
html=html.replace('Online availability depends on the connected rendering workers. AI Images, AI Video and Eye Contact require suitable GPU capacity. Shared social publishing is a separate rollout.','Both editions process on your computer. AI Images, AI Video and Eye Contact need compatible hardware and models. Editor integrations import new results; support varies by host version. They do not convert every generated effect into a native editable host effect.')
html=html.replace('Launch preview: purchases are not open yet. Processing and storage allowances will be shown before checkout. This is not an unlimited GPU plan.','Payments remain disabled until merchant verification, email delivery, signed releases and device activation are connected. Annual billing is fixed-term with manual renewal. Desktop and Editor Plugins are separate purchases.')
html=html.replace('Your private upload and export workspace','Local processing on your own computer').replace('Access to enabled editing tools','Access to the purchased edition').replace('?v=20261014c','?v=20261015a')
index.write_text(html,encoding='utf-8')
